/**
 * The journal, from mermademarket.com/blogs/journal.
 *
 * `body` is each article's own rich-text block, kept as HTML because that is
 * what it is: their writing, their emphasis, their links, and the
 * photographs interleaved through it. Rewriting it into JSX would only be an
 * opportunity to change it by accident.
 *
 * The photographs were pulled from their CDN and vendored under
 * /theme/img/posts (Shopify transcodes their HEIC originals to JPEG when a
 * width is requested, which is how the .heic ones got here). The only edit to
 * the markup is the rewritten image src and a `loading="lazy"` on every
 * <img>.
 *
 * `excerpt` is the first 160 characters of the body's visible text, which is
 * what their article cards show.
 *
 * Generated. Re-run the extraction rather than editing by hand.
 */
export type JournalPost = {
  slug: string
  title: string
  /** Their published timestamp, in UTC, exactly as their <time> carries it. */
  date: string
  /** The hero, from our earlier port. */
  image: string | null
  /** The article body, as HTML. */
  body: string
  excerpt: string
  /** Their own tags, shown under the article. Several posts carry none. */
  tags: string[]
}

